"""5100-style photo / rejected baseline / corrected 029 evidence page."""
import argparse,json,shutil,hashlib
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont,ImageOps
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--renders',type=Path,required=True);a=p.parse_args()
out=ROOT/'work/preview/029-comparison';out.mkdir(parents=True,exist_ok=True)
manifest=json.loads((ROOT/'models/029-photo-cameras.json').read_text());after=json.loads((a.candidate/'report.json').read_text());before=json.loads((ROOT/'work/029-refinement/baseline/report.json').read_text())
font=ImageFont.truetype('/usr/share/fonts/gnu-free/FreeSans.otf',22);rows=[]
for view in manifest['views']:
 name=view['id'];photo=Image.open(ROOT/view['photo']).convert('RGB');photo.save(out/(name+'-photo.jpg'),quality=94)
 for tag in ('before','after'):shutil.copyfile(a.renders/(name+'-'+tag+'.png'),out/(name+'-'+tag+'.png'))
 images=[photo]+[Image.open(out/(name+'-'+tag+'.png')).convert('RGB') for tag in ('before','after')]
 w,h=view['size'];sheet=Image.new('RGB',(w*3,h+48),'#18232a');d=ImageDraw.Draw(sheet)
 for i,(im,title) in enumerate(zip(images,['Original photograph','Old / bad procedural model','Corrected procedural model'])):
  sheet.paste(im,(i*w,48));d.text((i*w+12,10),title,font=font,fill='white')
 sheet.save(out/(name+'-sheet.jpg'),quality=92)
 fit=(f"Desk/leg camera-fit RMS: {view['fit_rms_coordinate_px']:.1f} pixels per coordinate. The housing and keyboard were excluded from camera fitting." if view['fit_rms_coordinate_px'] is not None else 'Approximate fixed framing: the cropped photo has no usable desk/foot fit. Both model renders still use exactly the same camera.')
 figures=''.join(f'<figure><a href="{name}-{suffix}"><img src="{name}-{suffix}" alt="{title}"></a><figcaption>{title}</figcaption></figure>' for suffix,title in [('photo.jpg','Original photo'),('before.png','Old / bad model'),('after.png','Corrected model')])
 rows.append(f'''<section><h2>{'IBM manual: complete machine' if name=='manual' else 'Columbia color close-up'}</h2><p><a href="{view['source_page']}">{view['credit']}</a>. {fit}</p><div class="triptych">{figures}</div><p><a href="{name}-sheet.jpg">Full-resolution three-panel sheet</a></p><details><summary>Overlay the corrected model on the photo</summary><label>Render opacity <input type="range" min="0" max="100" value="50" oninput="this.parentElement.nextElementSibling.lastElementChild.style.opacity=this.value/100"></label><div class="overlay"><img src="{name}-photo.jpg" alt="Photo"><img src="{name}-after.png" style="opacity:.5" alt="Corrected render"></div></details></section>''')
# Retain a complete, unclipped studio overview, independent of imperfect photo fit.
for tag,path in [('before',ROOT/'work/ibm029/candidate-20261110-123616-366006/overview.png'),('after',a.candidate/'overview.png')]:shutil.copyfile(path,out/('overview-'+tag+'.png'))
shutil.copyfile(ROOT/'references/029-columbia-029b.jpg',out/'photo.jpg')
shutil.copyfile(ROOT/'work/029-refinement/baseline/model.glb',out/'before.glb');shutil.copyfile(a.candidate/'ibm029.glb',out/'after.glb')
shutil.copyfile(ROOT/'models/029-photo-cameras.json',out/'locked-cameras.json');shutil.copyfile(ROOT/'work/029-refinement/camera-fit.jpg',out/'camera-fit.jpg')
report={'before_source':'work/ibm029/candidate-20261110-123616-366006','candidate':str(a.candidate),'before_sha256':hashlib.sha256((out/'before.glb').read_bytes()).hexdigest(),'after_sha256':hashlib.sha256((out/'after.glb').read_bytes()).hexdigest(),'before':{k:before[k] for k in ('mesh_count','triangle_count','glb_bytes')},'after':{k:after[k] for k in ('mesh_count','triangle_count','glb_bytes')},'camera_policy':manifest['camera_policy'],'changes':['Solid ramp replaced by open horizontal card path and split upper covers','Left sloping stacker, right open top hopper, guides, rollers and program drum window rebuilt','49 separate keycaps including space bar, traced from 48 numbered manual positions; two L-shaped caps','Switch panel height 120 to 85 mm; rake increases from 20.6 to 27.9 degrees from vertical','Program inspection face tilted back 12 degrees so window faces upward','Rear cabinet depth 190 mm of 760 mm tabletop, leaving 570 mm nominal open depth','Separate supported keyboard pod with 40 mm clear gap to the head'],'remaining':['Overall head and desk proportions are still inferred; the manual fit clips the head at top and exposes this mismatch','Photo color viewpoint is approximate, not calibrated','Exact concealed punch mechanism, cover curvature, card guides, materials and legends require further refinement']}
if (ROOT/'work/029-refinement/operator-clearance.json').exists():
 report['operator_clearance']=json.loads((ROOT/'work/029-refinement/operator-clearance.json').read_text())
(out/'measurements.json').write_text(json.dumps(report,indent=2)+'\n')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IBM 029 · Photo / old / corrected comparison</title><link rel="icon" href="data:,"><style>body{margin:0;background:#172027;color:#e6edf0;font:16px system-ui;line-height:1.5}main{max-width:1700px;padding:28px 24px;margin:auto}a{color:#89d8e5}h1{font-size:34px}section{border-top:1px solid #52616a;margin-top:28px;padding-top:20px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}figure{margin:0}img{display:block;width:100%}figcaption{padding:10px;background:#223039}.overlay{position:relative;max-width:1024px}.overlay img:last-child{position:absolute;inset:0}.notice{padding:18px;background:#26343e}button{padding:8px}details{margin:18px 0}@media(max-width:750px){.triptych{grid-template-columns:1fr}}</style><main><a href="../new-models.html">All equipment previews</a> · <a href="../equipment.html?model=029">Corrected interactive 029</a><h1>IBM 029: photo / old model / corrected model</h1><p>The old model was an inaccurate first pass. The revision follows the photos and keyboard diagram on <a href="https://www.columbia.edu/cu/computinghistory/029.html">Columbia University Computing History</a>, which reproduces IBM manual A24-3332-1.</p><div class="notice">Both model columns use identical frozen cameras, lights, exposure and image dimensions. The manual camera uses unchanged desk and foot landmarks; interior assemblies did not drive the camera fit. The color close-up uses approximate fixed framing. Camera residuals and model proportions remain visible rather than being hidden by independent crops.</div><h2>What changed</h2><ul><li>Replaced the solid sloping slab and three picture-frame trays with an open card route under separate upper covers.</li><li>Added the sloping left stacker, central transport rails, right hopper and throat, rollers, wire guide, and program drum.</li><li>Rebuilt the keyboard from the manual diagram, including the asymmetric ERROR RESET and LEFT ZERO caps, blue function keys and a spacebar.</li><li>Shortened the switch panel from 120 to 85 mm and increased its backward rake.</li><li>Tilted the program-window face back 12° so it faces slightly upward.</li><li>Replaced the deep lower box with a shallow rear cabinet: 190 mm depth under a 760 mm tabletop, leaving the front 570 mm (three quarters) open for operator legs.</li><li>Separated the keyboard pod from the main head with approximately 40 mm of visible tabletop; short feet support it at the desktop.</li></ul><p><a href="measurements.json">Changes, complexity and limitations</a> · <a href="locked-cameras.json">Frozen cameras</a> · <a href="camera-fit.jpg">Camera-fit diagnostic</a> · <a href="before.glb" download>Old GLB</a> · <a href="after.glb" download>Corrected GLB</a></p>ROWS<section><h2>Complete studio views</h2><p>These use the same existing overview camera for both models, so the full machine can be inspected independently of the imperfect photo-camera fit.</p><div class="triptych"><figure><img src="photo.jpg" alt="Original complete machine"><figcaption>Original photograph (different viewpoint)</figcaption></figure><figure><img src="overview-before.png" alt="Old overview"><figcaption>Old studio overview</figcaption></figure><figure><img src="overview-after.png" alt="Corrected overview"><figcaption>Corrected studio overview</figcaption></figure></div></section><section><h2>Still unresolved</h2><p>Absolute dimensions, the complete head-to-desk proportions, cover curvature, hidden punch mechanism and exact card-guide geometry remain provisional. The manual camera clips the modeled head at the top; this residual is shown openly. Do not treat successful export or camera fit as proof of historical accuracy.</p><p>Reference photos are preserved unchanged. Display JPEGs and labeled comparison sheets are derived copies. IBM manual images and the uncredited color photo retain their original rights and are not included under the code’s MIT license. The supplied reconstruction is not used as geometry or photographic ground truth in this correction.</p></section></main></html>'''
(out/'index.html').write_text(page.replace('ROWS',''.join(rows)))
selection=ROOT/'work/029-refinement/current.json';selection.write_text(json.dumps({'candidate':str(a.candidate),'renders':str(a.renders),'report':str(out/'measurements.json')},indent=2)+'\n')
print('Comparison page: http://192.168.1.178:5803/029-comparison/')
